import{_ as r,I as n,b as s,d as o,ah as a,J as i}from"./chunks/framework.7NXsYIIo.js";const b=JSON.parse('{"title":"Node.js prerequisites and topic boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"node-js/prerequisites-and-boundaries.md","filePath":"node-js/prerequisites-and-boundaries.md"}'),d={name:"node-js/prerequisites-and-boundaries.md"};function c(l,e,p,h,u,m){const t=n("MermaidDiagram");return o(),s("div",null,[e[0]||(e[0]=a('<h1 id="node-js-prerequisites-and-topic-boundaries" tabindex="-1">Node.js prerequisites and topic boundaries <a class="header-anchor" href="#node-js-prerequisites-and-topic-boundaries" aria-label="Permalink to “Node.js prerequisites and topic boundaries”">​</a></h1><p>Node provides an environment for running JavaScript. Closures, promises and object identity follow the same language rules as in a browser. <strong>The available APIs and permissions depend on the environment.</strong> Node adds filesystem access, processes and scheduling through libuv; browser JavaScript has different host APIs.</p><h2 id="shared-language-references" tabindex="-1"><span class="hub-section-number">1 </span>Shared language references <a class="header-anchor" href="#shared-language-references" aria-label="Permalink to “1 Shared language references”">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Existing explanation</th><th>Boundary to remember</th></tr></thead><tbody><tr><td>Bindings, call stack and captured lifetime</td><td><a href="./../senior_growth/General_ES6/Explain_JavaScript_Code_Execution_177e8106c24d80a0817df62da9bac253.html">JavaScript execution</a></td><td>Stack/heap diagrams are conceptual; GC timing is not resource cleanup</td></tr><tr><td>Promise adoption, derived chains and combinators</td><td><a href="./../senior_growth/General_ES6/What_is_a_Promise_177e8106c24d80b3989df334146152f6.html">Promises</a></td><td>Neither a promise nor <code>Promise.all</code> grants cancellation or concurrency limits</td></tr><tr><td>Sequential dependencies and complete operation lifetimes</td><td><a href="./../senior_growth/General_ES6/Understanding_async_await_in_JavaScript_177e8106c24d806fb457f53520e2c087.html">Async/await</a></td><td>Await does not move synchronous work off-thread</td></tr><tr><td>Tasks, microtasks and host differences</td><td><a href="./../senior_growth/General_ES6/What_are_the_tasks_microtasks_177e8106c24d804f94a8c0f84060cdf2.html">Task/microtask reference</a></td><td>Use Module 1 for Node phases, nextTick and CJS/ESM context</td></tr><tr><td>Legacy callback interoperation</td><td><a href="./../senior_growth/Other/What_is_the_callback_hell_How_can_you_avoid_it.html">Callback workflow</a></td><td>An adapter needs error, settlement and lifetime ownership</td></tr><tr><td>Public module surface and notification buses</td><td><a href="./../senior_growth/Other/What_is_module_How_to_build_communication_between_modules.html">Modules</a></td><td>A custom awaited bus has different semantics from synchronous EventEmitter</td></tr><tr><td>Interactive exploration</td><td><a href="./../senior_growth/General_ES6/Explain_Read_Eval_Print_Loop_in_NodeJS_177e8106c24d803babd4caa58acdfd5b.html">REPL</a></td><td>REPL scope and <code>.clear</code> differ from file evaluation; history/effects can persist</td></tr></tbody></table><p>These are shared references, not additional compulsory projects. Their browser examples and exercises belong to their broader JavaScript topic. The <a href="./../practice/node-js/">Node practice map</a> identifies the runtime-specific work.</p><h2 id="keep-the-ownership-boundaries-visible" tabindex="-1"><span class="hub-section-number">2 </span>Keep the ownership boundaries visible <a class="header-anchor" href="#keep-the-ownership-boundaries-visible" aria-label="Permalink to “2 Keep the ownership boundaries visible”">​</a></h2>',6)),i(t,{"encoded-source":"flowchart%20TD%0A%20%20%20%20JS%5BJavaScript%20language%5D%20--%3E%20Runtime%5BNode%20runtime%20and%20standard%20library%5D%0A%20%20%20%20Runtime%20--%3E%20CLI%5BCLI%20and%20bounded%20file%20processing%5D%0A%20%20%20%20Runtime%20--%3E%20HTTP%5BHTTP%20service%20and%20lifecycle%5D%0A%20%20%20%20HTTP%20--%3E%20Backend%5BExpress%20and%20application%20policy%5D%0A%20%20%20%20Backend%20--%3E%20Data%5BSQL%20and%20persistence%5D%0A%20%20%20%20Backend%20--%3E%20Delivery%5BDeployment%20and%20durable%20jobs%5D"}),e[1]||(e[1]=a('<p>You can learn HTTP and streams without a framework. Express adds routing and middleware, but your application still checks permissions. Database lessons explain transactions and query plans; their Node clients must also handle cancellation and close connections. Deployment controls traffic and process replacement. <strong>It does not make unfinished writes or in-memory jobs survive a restart</strong>, or clean up timers your code forgot to close.</p><p>Worker threads run JavaScript in separate execution environments inside one process. Browser Web Workers use a different API. libuv&#39;s native worker pool is a third mechanism used by selected Node operations. <strong>Neither <code>async</code> nor a thread creates a security sandbox.</strong> File, network and application permissions still need explicit controls.</p><h2 id="essential-depth-and-extensions" tabindex="-1"><span class="hub-section-number">3 </span>Essential depth and extensions <a class="header-anchor" href="#essential-depth-and-extensions" aria-label="Permalink to “3 Essential depth and extensions”">​</a></h2><p>First, learn to explain runtime behavior and independently build and debug a small CLI or HTTP program with clear limits on input, time and work. Add readiness checks, diagnostics and clean shutdown. Continue to an authenticated PostgreSQL service when you need backend integration. Add deployment and durable jobs when the work must survive restarts and support recovery.</p><p>You do not need a complete worker-pool framework, several databases, a learned agent, a general-purpose file parser or cloud/cluster administration to complete the core runtime course. Those introductory and follow-on lessons remain available when you need them.</p>',5))])}const f=r(d,[["render",c]]);export{b as __pageData,f as default};
